INSERT INTO news_review.members VALUES('33333333-3333-4333-8333-333333333333','reviewer');
SELECT set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
SET LOCAL ROLE authenticated;
DO $$
DECLARE doc jsonb:='{"verification":{"headline":"Crude-oil supply disruption","summary":"A reported disruption may raise producer receipts and airline costs.","acceptance_reason":"Relevant for monitoring; confirmation is incomplete.","category":"macro","verification_status":"partially_verified","source_classification":"Primary industry report","source_credibility":0.8,"occurrence_certainty":"unknown","novelty":"new"},"evidence":[{"id":"44444444-4444-4444-8444-444444444444","added_at":"2026-09-28T00:00:00Z","fields":{"label":"Source report","url":"https://example.com/supply-report","classification":"Primary report"}}],"event_ids":[],"mappings":[{"id":"55555555-5555-4555-8555-555555555555","fields":{"entity_id":"11111111-1111-4111-8111-111111111111","entity_type":"company","relationship":"beneficiary","exposure":"direct","transmission":"Higher crude prices increase realized producer revenue","mapping_confidence":0.8,"mapping_reason":"Exposure supported by operating model and source reference"},"chain":[],"impact":{"direction":"positive","magnitude":"high","rationale":"Supply disruption changes operating economics","metrics_status":"specified","effect_type":"fundamentals","impact_confidence":0.7,"surprise":"unknown","anticipated":"unknown","assumptions":"Disruption persists long enough to affect contracted prices"},"metrics":[{"name":"Revenue","change":"increase","implication":"beneficial","evidence_id":"44444444-4444-4444-8444-444444444444"}],"horizons":[{"horizon":"short_term","direction":"positive","magnitude":"high","confidence":0.7,"timing_rationale":"Spot prices adjust before contract resets","review_date":"2026-10-20","persistence":"temporary","date_certainty":"unknown"},{"horizon":"long_term","direction":"neutral","magnitude":"low","confidence":0.4,"timing_rationale":"Supply normalizes and hedges adjust","review_date":"2027-06-01","persistence":"unknown","date_certainty":"unknown"}],"advanced":{}},{"id":"66666666-6666-4666-8666-666666666666","fields":{"entity_id":"22222222-2222-4222-8222-222222222222","entity_type":"company","relationship":"customer","exposure":"indirect","transmission":"Fuel costs reduce airline margins","mapping_confidence":0.8,"mapping_reason":"Exposure supported by operating model and source reference"},"chain":["Crude supply disruption","Higher jet-fuel costs","Airline margin pressure"],"impact":{"direction":"negative","magnitude":"high","rationale":"Supply disruption changes operating economics","metrics_status":"specified","effect_type":"fundamentals","impact_confidence":0.7,"surprise":"unknown","anticipated":"unknown","assumptions":"Disruption persists long enough to affect contracted prices"},"metrics":[{"name":"Fuel costs","change":"increase","implication":"adverse","evidence_id":"44444444-4444-4444-8444-444444444444"}],"horizons":[{"horizon":"short_term","direction":"negative","magnitude":"high","confidence":0.7,"timing_rationale":"Spot prices adjust before contract resets","review_date":"2026-10-20","persistence":"temporary","date_certainty":"unknown"},{"horizon":"long_term","direction":"positive","magnitude":"low","confidence":0.4,"timing_rationale":"Supply normalizes and hedges adjust","review_date":"2027-06-01","persistence":"unknown","date_certainty":"unknown"}],"advanced":{}}]}';d jsonb;v jsonb;revised jsonb;pending jsonb;before_snapshot jsonb;res jsonb;version_id uuid;event_id uuid;feed jsonb;
BEGIN
 d:=public.review_workflow('save',jsonb_build_object('article',repeat('f',40),'document',doc));
 BEGIN PERFORM public.review_workflow('save',jsonb_build_object('article',repeat('f',40),'draft_id',d->>'id','revision',99,'document',doc));RAISE EXCEPTION 'Stale draft edit allowed';EXCEPTION WHEN SQLSTATE 'PT409' THEN NULL;END;
 BEGIN PERFORM public.review_workflow('accept',jsonb_build_object('draft_id',d->>'id','revision',99,'outcome','accepted_analysis_ready'));RAISE EXCEPTION 'Stale acceptance allowed';EXCEPTION WHEN SQLSTATE 'PT409' THEN NULL;END;
 v:=public.review_workflow('accept',jsonb_build_object('draft_id',d->>'id','revision',0,'outcome','accepted_analysis_ready'));
 version_id:=(v->>'version_id')::uuid;event_id:=(v->>'event_id')::uuid;
 res:=public.review_workflow('accept',jsonb_build_object('draft_id',d->>'id','revision',0,'outcome','accepted_analysis_ready'));
 IF res->>'version_id'<>v->>'version_id' OR res->>'alreadyAccepted'<>'true' THEN RAISE EXCEPTION 'Idempotency failed';END IF;
 feed:=public.review_workflow('feed','{}');
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(feed) x WHERE x->>'id'=v->>'version_id') THEN RAISE EXCEPTION 'Analysis-ready version missing from feed';END IF;
 IF (SELECT count(*) FROM public.impact_records WHERE review_version_id=version_id)<>2 THEN RAISE EXCEPTION 'Entity projections missing';END IF;
 BEGIN UPDATE public.impact_records SET summary='tampered' WHERE review_version_id=version_id;RAISE EXCEPTION 'Reviewer edited managed projection';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 before_snapshot:=public.review_workflow('load',jsonb_build_object('article',repeat('f',40)))->'versions'->0->'snapshot';
 PERFORM public.review_workflow('observe',jsonb_build_object('version_id',version_id,'fields',jsonb_build_object('analysis_date',current_date::text,'cutoff_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US'),'entity_id','22222222-2222-4222-8222-222222222222','assessment','Review carried forward; no market data available','mode','carried_forward','revision_reason','First manual follow-up','outcome','pending')));
 IF public.review_workflow('load',jsonb_build_object('article',repeat('f',40)))->'versions'->0->'snapshot'<>before_snapshot THEN RAISE EXCEPTION 'Observation mutated forecast';END IF;
 BEGIN PERFORM public.review_workflow('observe',jsonb_build_object('version_id',version_id,'fields',jsonb_build_object('analysis_date','2000-01-01','cutoff_at','2000-01-01T12:00','entity_id','22222222-2222-4222-8222-222222222222','assessment','Backfill','mode','recomputed','revision_reason','test','outcome','pending')));RAISE EXCEPTION 'Backdated forecast allowed';EXCEPTION WHEN SQLSTATE 'PT400' THEN NULL;END;
 revised:=public.review_workflow('save',jsonb_build_object('article',repeat('f',40),'document',jsonb_set(doc,'{mappings}','[]')));
 BEGIN PERFORM public.review_workflow('accept',jsonb_build_object('draft_id',revised->>'id','revision',0,'outcome','accepted_analysis_ready'));RAISE EXCEPTION 'Incomplete analysis accepted';EXCEPTION WHEN SQLSTATE 'PT400' THEN NULL;END;
 pending:=public.review_workflow('accept',jsonb_build_object('draft_id',revised->>'id','revision',0,'outcome','accepted_pending_enrichment'));
 IF pending->>'version_id'=v->>'version_id' THEN RAISE EXCEPTION 'Accepted history overwritten';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(public.review_workflow('feed','{}')) x WHERE x->>'article_key'=repeat('f',40)) THEN RAISE EXCEPTION 'Pending version appears as ready';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.review_workflow('feed','{"mode":"pending"}')) x WHERE x->>'id'=pending->>'version_id') THEN RAISE EXCEPTION 'Pending queue missing';END IF;
 BEGIN PERFORM public.news_workspace('review',jsonb_build_object('id',repeat('f',40),'decision','accepted'));RAISE EXCEPTION 'Legacy acceptance bypass';EXCEPTION WHEN SQLSTATE 'PT409' THEN NULL;END;
END $$;
RESET ROLE;
DO $$ DECLARE original jsonb; count_before int; d jsonb; BEGIN
 BEGIN UPDATE news_review.versions SET snapshot='{}' WHERE article_key=repeat('f',40);RAISE EXCEPTION 'History mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN DELETE FROM news_review.audit WHERE article_key=repeat('f',40);RAISE EXCEPTION 'Audit mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF (SELECT count(*) FROM news_review.scores s JOIN news_review.versions v ON v.id=s.version_id WHERE v.article_key=repeat('f',40))<>6 THEN RAISE EXCEPTION 'Missing entity or horizon scores';END IF;
 IF EXISTS(SELECT 1 FROM public.impact_records i JOIN news_review.versions v ON v.id=i.review_version_id WHERE v.article_key=repeat('f',40) AND i.analysis_current) THEN RAISE EXCEPTION 'Superseded projection still current';END IF;
END $$;
