-- Inject a projection failure after version/evidence writes to prove statement atomicity.
CREATE FUNCTION news_review.test_projection_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.summary='__force_failure__' THEN RAISE EXCEPTION 'Injected projection failure' USING ERRCODE='23514'; END IF;RETURN NEW; END $$;
CREATE TRIGGER test_projection_failure BEFORE INSERT ON public.impact_records FOR EACH ROW EXECUTE FUNCTION news_review.test_projection_failure();
SELECT set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
SET LOCAL ROLE authenticated;
DO $$
DECLARE loaded jsonb;d jsonb;doc jsonb;before_count int;after_count int;
BEGIN
 loaded:=public.review_workflow('load',jsonb_build_object('article',repeat('f',40)));
 before_count:=jsonb_array_length(loaded->'versions');
 doc:=loaded->'versions'->1->'snapshot';
 doc:=jsonb_set(doc,'{mappings,0,impact,rationale}','"__force_failure__"');
 d:=public.review_workflow('save',jsonb_build_object('article',repeat('f',40),'document',doc));
 BEGIN PERFORM public.review_workflow('accept',jsonb_build_object('draft_id',d->>'id','revision',0,'outcome','accepted_analysis_ready'));RAISE EXCEPTION 'Injected failure did not occur';EXCEPTION WHEN check_violation THEN NULL;END;
 loaded:=public.review_workflow('load',jsonb_build_object('article',repeat('f',40)));
 after_count:=jsonb_array_length(loaded->'versions');
 IF before_count<>after_count OR loaded->'draft'->>'accepted_version' IS NOT NULL THEN RAISE EXCEPTION 'Acceptance did not roll back atomically';END IF;
END $$;
RESET ROLE;
DROP TRIGGER test_projection_failure ON public.impact_records;
DROP FUNCTION news_review.test_projection_failure();
