INSERT INTO news_review.members VALUES('88888888-8888-4888-8888-888888888888','reviewer');
DO $$
DECLARE d1 jsonb;d2 jsonb;doc jsonb;
BEGIN
 PERFORM set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
 d1:=public.review_workflow('restart',jsonb_build_object('article',repeat('f',40)));
 PERFORM set_config('request.jwt.claim.sub','88888888-8888-4888-8888-888888888888',true);
 d2:=public.review_workflow('restart',jsonb_build_object('article',repeat('f',40)));
 PERFORM public.review_workflow('accept',jsonb_build_object('draft_id',d2->>'id','revision',0,'outcome','accepted_pending_enrichment'));
 PERFORM set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
 BEGIN PERFORM public.review_workflow('accept',jsonb_build_object('draft_id',d1->>'id','revision',0,'outcome','accepted_pending_enrichment'));RAISE EXCEPTION 'Stale concurrent review accepted';EXCEPTION WHEN SQLSTATE 'PT409' THEN NULL;END;
 d1:=public.review_workflow('restart',jsonb_build_object('article',repeat('f',40)));
 PERFORM public.review_workflow('accept',jsonb_build_object('draft_id',d1->>'id','revision',0,'outcome','accepted_pending_enrichment'));
END $$;
